public class OverdueInvoiceBatch implements Database.Batchable<sObject> {

    private Integer recordsUpdated = 0;
    private Integer recordsFailed = 0;
    private Decimal overdueAmount = 0.0;

    public OverdueInvoiceBatch() {
        // No-argument constructor
    }

    public Database.QueryLocator start(Database.BatchableContext bc) {
        String query = 'SELECT Id, Status__c, Due_Date__c, Amount__c, Customer_Email__c ' +
                      'FROM FB_Invoice__c ' +
                      'WHERE Status__c = \'Open\' AND Due_Date__c < TODAY';
        return Database.queryLocator(query);
    }

    public void execute(Database.BatchableContext bc, List<sObject> records) {
        List<FB_Invoice__c> invoices = (List<FB_Invoice__c>) records;

        for (FB_Invoice__c invoice : invoices) {
            try {
                invoice.Status__c = 'Overdue';
                update invoice;
                recordsUpdated++;
                if (invoice.Amount__c != null) {
                    overdueAmount += invoice.Amount__c;
                }
            } catch (Exception e) {
                recordsFailed++;
            }
        }
    }

    public void finish(Database.BatchableContext bc) {
        FB_Job_Summary__c summary = new FB_Job_Summary__c();
        summary.Job_Name__c = 'OverdueInvoiceBatch';
        summary.Records_Updated__c = recordsUpdated;
        summary.Records_Failed__c = recordsFailed;
        summary.Overdue_Amount__c = overdueAmount;

        insert summary;
    }
}
