public class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public static Order parse(String body) {
        if (body == null || body.trim().length() == 0) {
            throw new PayloadException('Body is null or blank');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON: ' + e.getMessage());
        }

        if (!(parsed instanceof Map)) {
            throw new PayloadException('JSON is not an object');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;

        if (!root.containsKey('number') || root.get('number') == null || 
            ((String) root.get('number')).trim().length() == 0) {
            throw new PayloadException('Missing or blank order number');
        }
        String orderNumber = (String) root.get('number');

        Date orderDate = null;
        if (root.containsKey('date') && root.get('date') != null) {
            String dateStr = (String) root.get('date');
            try {
                orderDate = Date.parse(dateStr);
            } catch (Exception e) {
                throw new PayloadException('Invalid date format');
            }
        }

        String currencyCode = null;
        if (root.containsKey('currency') && root.get('currency') != null) {
            currencyCode = (String) root.get('currency');
        }

        String customerEmail = null;
        if (root.containsKey('customer') && root.get('customer') != null && 
            root.get('customer') instanceof Map) {
            Map<String, Object> customer = (Map<String, Object>) root.get('customer');
            if (customer.containsKey('email') && customer.get('email') != null) {
                customerEmail = (String) customer.get('email');
            }
        }

        List<Line> lines = new List<Line>();
        if (root.containsKey('lines') && root.get('lines') != null && 
            root.get('lines') instanceof List) {
            List<Object> linesList = (List<Object>) root.get('lines');
            for (Object lineObj : linesList) {
                if (!(lineObj instanceof Map)) {
                    throw new PayloadException('Line item is not an object');
                }
                Map<String, Object> lineMap = (Map<String, Object>) lineObj;

                if (!lineMap.containsKey('sku') || lineMap.get('sku') == null || 
                    ((String) lineMap.get('sku')).trim().length() == 0) {
                    throw new PayloadException('Missing or blank sku in line item');
                }
                String sku = (String) lineMap.get('sku');

                if (!lineMap.containsKey('quantity') || lineMap.get('quantity') == null) {
                    throw new PayloadException('Missing quantity in line item');
                }
                Integer quantity;
                try {
                    quantity = (Integer) lineMap.get('quantity');
                } catch (Exception e) {
                    throw new PayloadException('Invalid quantity in line item');
                }
                if (quantity <= 0) {
                    throw new PayloadException('Non-positive quantity in line item');
                }

                if (!lineMap.containsKey('unitPrice') || lineMap.get('unitPrice') == null) {
                    throw new PayloadException('Missing unitPrice in line item');
                }
                Decimal unitPrice;
                try {
                    unitPrice = (Decimal) lineMap.get('unitPrice');
                } catch (Exception e) {
                    throw new PayloadException('Invalid unitPrice in line item');
                }
                if (unitPrice < 0) {
                    throw new PayloadException('Negative unitPrice in line item');
                }

                Decimal discount = 0;
                if (lineMap.containsKey('discount') && lineMap.get('discount') != null) {
                    discount = (Decimal) lineMap.get('discount');
                }

                Decimal lineTotal = quantity * unitPrice * (1 - discount);
                lineTotal = Math.round(lineTotal * 100) / 100;

                Line line = new Line();
                line.sku = sku;
                line.quantity = quantity;
                line.unitPrice = unitPrice;
                line.discount = discount;
                line.lineTotal = lineTotal;
                lines.add(line);
            }
        }

        Decimal total = 0;
        for (Line line : lines) {
            total += line.lineTotal;
        }

        Order order = new Order();
        order.orderNumber = orderNumber;
        order.orderDate = orderDate;
        order.currencyCode = currencyCode;
        order.customerEmail = customerEmail;
        order.lines = lines;
        order.total = total;

        return order;
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines.size());
        ack.put('total', order.total);

        return JSON.serialize(ack);
    }
}
