public class LeadImportService {
    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            successCount = 0;
            insertedIds = new List<Id>();
            errorsByIndex = new Map<Integer, String>();
        }
    }

    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        // Handle null or empty input
        if (leads == null || leads.isEmpty()) {
            return result;
        }

        // Preprocess: set LeadSource to 'Web' if blank
        for (Lead lead : leads) {
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }
        }

        // Track duplicate emails
        Map<String, Integer> emailToFirstIndex = new Map<String, Integer>();
        Map<Integer, String> duplicateErrors = new Map<Integer, String>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead lead = leads[i];
            String email = lead.Email;

            // Only check duplicates if email is not null and not blank after trimming
            if (email != null && String.isNotBlank(email.trim())) {
                String normalizedEmail = email.trim().toLowerCase();
                if (emailToFirstIndex.containsKey(normalizedEmail)) {
                    // Duplicate found
                    duplicateErrors.put(i, 'Duplicate email in import: ' + normalizedEmail);
                } else {
                    emailToFirstIndex.put(normalizedEmail, i);
                }
            }
        }

        // Build list of leads to insert (excluding duplicates)
        List<Lead> leadsToInsert = new List<Lead>();
        List<Integer> originalIndicesForInsert = new List<Integer>();

        for (Integer i = 0; i < leads.size(); i++) {
            // If this lead is a duplicate, skip it
            if (duplicateErrors.containsKey(i)) {
                continue;
            }
            leadsToInsert.add(leads[i]);
            originalIndicesForInsert.add(i);
        }

        // If no leads to insert, return result with duplicate errors
        if (leadsToInsert.isEmpty()) {
            result.errorsByIndex = duplicateErrors;
            return result;
        }

        // Perform single DML insert with allOrNone=false
        List<Database.SaveResult> saveResults = Database.insert(leadsToInsert, false);

        // Process save results
        Map<Integer, Id> insertedIdsByIndex = new Map<Integer, Id>();
        Map<Integer, String> dmlErrors = new Map<Integer, String>();

        for (Integer j = 0; j < saveResults.size(); j++) {
            Database.SaveResult sr = saveResults[j];
            Integer originalIndex = originalIndicesForInsert[j];

            if (sr.isSuccess()) {
                insertedIdsByIndex.put(originalIndex, sr.getId());
            } else {
                // Collect error messages
                List<Database.Error> errors = sr.getErrors();
                String errorMessage = '';
                for (Database.Error err : errors) {
                    if (errorMessage != '') {
                        errorMessage += '; ';
                    }
                    errorMessage += err.getMessage();
                }
                dmlErrors.put(originalIndex, errorMessage);
            }
        }

        // Build final result
        // Inserted IDs in input order
        for (Integer i = 0; i < leads.size(); i++) {
            if (insertedIdsByIndex.containsKey(i)) {
                result.insertedIds.add(insertedIdsByIndex.get(i));
                result.successCount++;
            }
        }

        // Combine duplicate errors and DML errors
        // Duplicate errors are already in duplicateErrors map
        // DML errors are in dmlErrors map
        // We need to merge them into result.errorsByIndex
        for (Integer idx : duplicateErrors.keySet()) {
            result.errorsByIndex.put(idx, duplicateErrors.get(idx));
        }
        for (Integer idx : dmlErrors.keySet()) {
            result.errorsByIndex.put(idx, dmlErrors.get(idx));
        }

        return result;
    }
}
