public class PicklistService {
    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {}

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        // Validate inputs
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object and field API names must not be null or blank');
        }

        // Normalize case for API names
        String normalizedObjectApiName = objectApiName.trim();
        String normalizedFieldApiName = fieldApiName.trim();

        // Check if object exists
        Schema.SObjectType sObjectType = Schema.getGlobalDescribe().get(normalizedObjectApiName);
        if (sObjectType == null) {
            throw new PicklistServiceException('Object ' + normalizedObjectApiName + ' does not exist');
        }

        // Get field description
        Map<String, Schema.SObjectField> fieldMap = sObjectType.getDescribe().fields.getMap();
        Schema.SObjectField sObjectField = fieldMap.get(normalizedFieldApiName);
        if (sObjectField == null) {
            throw new PicklistServiceException('Field ' + normalizedFieldApiName + ' does not exist on object ' + normalizedObjectApiName);
        }

        // Get field describe result
        Schema.DescribeFieldResult fieldDescribe = sObjectField.getDescribe();

        // Check if field is a picklist or multi-select picklist
        Schema.DisplayType fieldType = fieldDescribe.getType();
        if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException('Field ' + normalizedFieldApiName + ' is not a picklist or multi-select picklist');
        }

        // Get picklist entries
        List<Schema.PicklistEntry> picklistEntries = fieldDescribe.getPicklistValues();

        // Get the default value for the field
        String defaultValue = fieldDescribe.getDefaultValue();

        // Build result list
        List<Option> options = new List<Option>();
        for (Schema.PicklistEntry entry : picklistEntries) {
            // Only include active values
            if (entry.isActive()) {
                Boolean isDefault = (defaultValue != null && defaultValue == entry.getValue());
                Option option = new Option(
                    entry.getValue(),
                    entry.getLabel(),
                    isDefault
                );
                options.add(option);
            }
        }

        return options;
    }
}
