public with sharing class LeadContactMatcher {
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> result = new List<Id>();

        // Build a map of normalized email to contact Id for O(1) lookup
        // This preserves the first contact in case of duplicate emails
        Map<String, Id> emailToContactId = new Map<String, Id>();

        for (Contact contact : contacts) {
            if (!String.isBlank(contact.Email)) {
                String normalizedEmail = contact.Email.trim().toLowerCase();
                // Only add if not already present (preserves first occurrence order)
                if (!emailToContactId.containsKey(normalizedEmail)) {
                    emailToContactId.put(normalizedEmail, contact.Id);
                }
            }
        }

        // Match each lead against the map
        for (Lead lead : leads) {
            Id matchedContactId = null;

            if (!String.isBlank(lead.Email)) {
                String normalizedLeadEmail = lead.Email.trim().toLowerCase();
                if (emailToContactId.containsKey(normalizedLeadEmail)) {
                    matchedContactId = emailToContactId.get(normalizedLeadEmail);
                }
            }

            result.add(matchedContactId);
        }

        return result;
    }
}
