public class CaseSurveyJob implements Queueable {
    private List<Id> caseIds;

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    public void execute(QueueableContext context) {
        // Query all cases in the batch
        List<Case> cases = [SELECT Id, CaseNumber, ContactId FROM Case WHERE Id IN :caseIds];

        List<Task> tasksToInsert = new List<Task>();

        for (Case caseRecord : cases) {
            // Only create task if case still has a contact
            if (caseRecord.ContactId != null) {
                Task surveyTask = new Task();
                surveyTask.WhatId = caseRecord.Id;
                surveyTask.WhoId = caseRecord.ContactId;
                surveyTask.Subject = 'CSAT survey: ' + caseRecord.CaseNumber;
                surveyTask.ActivityDate = Date.today().addDays(2);
                surveyTask.Status = 'Not Started';
                tasksToInsert.add(surveyTask);
            }
        }

        // Insert all tasks in bulk
        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
