```javascript
import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;

    @api
    set tasks(value) {
        // Create a copy of the tasks array and each task object
        this.items = value ? value.map(task => ({ ...task })) : [];
        // Initialize nextId based on existing IDs to avoid collisions
        if (this.items.length > 0) {
            const maxId = Math.max(...this.items.map(t => {
                const idNum = parseInt(t.id, 10);
                return isNaN(idNum) ? 0 : idNum;
            }));
            this.nextId = maxId + 1;
        } else {
            this.nextId = 1;
        }
    }

    get tasks() {
        return this.items;
    }

    get headingDisplay() {
        return this.heading ? this.heading.toUpperCase() : '';
    }

    items = [];
    newLabel = '';
    nextId = 1;

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = this.newLabel.trim();
        if (!label) {
            return;
        }
        this.items.push({ id: this.nextId++, label: label, done: false });
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label: label } }));
    }

    handleToggle(event) {
        const index = this.items.findIndex((t) => t.id === event.target.dataset.id);
        if (index !== -1) {
            const task = this.items[index];
            // Create a new array with the updated task to trigger reactivity
            this.items = [
                ...this.items.slice(0, index),
                { ...task, done: !task.done },
                ...this.items.slice(index + 1)
            ];
        }
    }
}
