public class HouseholdService {
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members cannot be null or empty');
        }

        // Ensure all contacts have a name by setting FirstName/LastName if needed
        // (Contact.Name may not be directly writeable in this org)
        for (Contact c : members) {
            if (String.isBlank(c.FirstName)) {
                c.FirstName = 'Unknown';
            }
            if (String.isBlank(c.LastName)) {
                c.LastName = 'Unknown';
            }
        }

        // Get the Household Account Record Type Id
        Id householdRecordTypeId = getHouseholdRecordTypeId();

        // Insert all contacts (they will get Ids)
        insert members;

        // Create the household account with the first contact as primary
        Account householdAccount = new Account(
            RecordTypeId = householdRecordTypeId,
            npe01__One2OneContact__c = members[0].Id
        );
        insert householdAccount;

        // Update all contacts to link to the household account
        for (Contact c : members) {
            c.AccountId = householdAccount.Id;
        }
        update members;

        return householdAccount.Id;
    }

    private static Id getHouseholdRecordTypeId() {
        RecordType rt = [SELECT Id FROM RecordType WHERE SObjectType = 'Account' AND DeveloperName = 'HH_Account' LIMIT 1];
        return rt.Id;
    }
}
