public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    public override npsp.TDTM_Runnable.DmlWrapper run(List<SObject> newlist, 
                                                       List<SObject> oldlist, 
                                                       npsp.TDTM_Runnable.Action triggerAction, 
                                                       Schema.DescribeSObjectResult objResult) {

        npsp.TDTM_Runnable.DmlWrapper wrapper = new npsp.TDTM_Runnable.DmlWrapper();

        // Only process after insert or after update
        if (triggerAction != npsp.TDTM_Runnable.Action.AFTER_INSERT && 
            triggerAction != npsp.TDTM_Runnable.Action.AFTER_UPDATE) {
            return wrapper;
        }

        List<Opportunity> opportunities = new List<Opportunity>();
        List<Opportunity> oldOpportunities = new List<Opportunity>();

        for (SObject sObj : newlist) {
            opportunities.add((Opportunity)sObj);
        }

        if (oldlist != null) {
            for (SObject sObj : oldlist) {
                oldOpportunities.add((Opportunity)sObj);
            }
        }

        // Collect opportunities that qualify for task creation
        List<Opportunity> qualifiedOpps = new List<Opportunity>();

        for (Integer i = 0; i < opportunities.size(); i++) {
            Opportunity opp = opportunities[i];
            Opportunity oldOpp = (i < oldOpportunities.size()) ? oldOpportunities[i] : null;

            if (shouldCreateTask(opp, oldOpp)) {
                qualifiedOpps.add(opp);
            }
        }

        if (qualifiedOpps.isEmpty()) {
            return wrapper;
        }

        // Query existing tasks for these opportunities (1 SOQL query)
        Map<Id, List<Task>> existingTasksByWhatId = new Map<Id, List<Task>>();
        List<Task> existingTasks = [SELECT Id, WhatId FROM Task WHERE WhatId IN :qualifiedOpps];

        for (Task t : existingTasks) {
            if (!existingTasksByWhatId.containsKey(t.WhatId)) {
                existingTasksByWhatId.put(t.WhatId, new List<Task>());
            }
            existingTasksByWhatId.get(t.WhatId).add(t);
        }

        // Create tasks for opportunities that don't already have one
        List<Task> tasksToInsert = new List<Task>();

        for (Opportunity opp : qualifiedOpps) {
            // Check if a task already exists for this opportunity
            if (existingTasksByWhatId.containsKey(opp.Id)) {
                // Task already exists, skip
                continue;
            }

            Task newTask = new Task();
            newTask.Subject = 'Major gift thank-you call';
            newTask.Priority = 'High';
            newTask.Status = 'Not Started';
            newTask.WhatId = opp.Id;
            newTask.WhoId = opp.npsp__Primary_Contact__c; // May be null
            newTask.OwnerId = opp.OwnerId;
            newTask.ActivityDate = opp.CloseDate.addDays(3);

            tasksToInsert.add(newTask);
        }

        // Insert tasks (1 DML statement)
        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        return wrapper;
    }

    private Boolean shouldCreateTask(Opportunity opp, Opportunity oldOpp) {
        // Check if opportunity is Closed Won and Amount >= 5000
        Boolean isClosedWonAndHighAmount = (opp.StageName == 'Closed Won' && opp.Amount >= 5000);

        if (!isClosedWonAndHighAmount) {
            return false;
        }

        // For AfterInsert, oldOpp is null, so we always create task if conditions met
        if (oldOpp == null) {
            return true;
        }

        // For AfterUpdate, check if it wasn't already Closed Won with Amount >= 5000
        Boolean wasClosedWonAndHighAmount = (oldOpp.StageName == 'Closed Won' && oldOpp.Amount >= 5000);

        // Create task only if it wasn't already qualified
        return !wasClosedWonAndHighAmount;
    }
}
