public with sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {
    public void afterInsert(List<SObject> triggerNew) {
        List<Account> accounts = (List<Account>) triggerNew;

        // Filter accounts that need onboarding tasks (only Customer - Direct or Customer - Channel)
        List<Account> qualifiedAccounts = new List<Account>();
        for (Account acc : accounts) {
            if (acc.Type == 'Customer - Direct' || acc.Type == 'Customer - Channel') {
                qualifiedAccounts.add(acc);
            }
        }

        // If no accounts qualify, return early with no DML
        if (qualifiedAccounts.isEmpty()) {
            return;
        }

        // Create tasks for all qualified accounts
        List<Task> tasks = new List<Task>();
        Date dueDate = Date.today().addDays(7);

        for (Account acc : qualifiedAccounts) {
            Task t = new Task();
            t.Subject = 'Onboard new customer';
            t.WhatId = acc.Id;
            t.OwnerId = acc.OwnerId;
            t.ActivityDate = dueDate;
            t.Status = 'Not Started';
            t.Priority = 'Normal';
            tasks.add(t);
        }

        // Single DML statement to insert all tasks
        insert tasks;
    }
}
