public class TA_Opportunity_CollectForErpSync implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    // Static set to collect Opportunity IDs that need syncing across all trigger chunks
    private static Set<Id> opportunityIdsToSync = new Set<Id>();

    public static Set<Id> getOpportunityIdsToSync() {
        return opportunityIdsToSync;
    }

    public static void clearCollectedIds() {
        opportunityIdsToSync = new Set<Id>();
    }

    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> oppIds = new Set<Id>();
        for (SObject s : triggerNew) {
            oppIds.add(s.Id);
        }
        opportunityIdsToSync.addAll(oppIds);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> oppIds = new Set<Id>();
        Map<Id, SObject> oldMap = new Map<Id, SObject>();
        for (SObject s : triggerOld) {
            oldMap.put(s.Id, s);
        }
        for (SObject s : triggerNew) {
            SObject old = oldMap.get(s.Id);
            if (old != null) {
                Opportunity newOpp = (Opportunity)s;
                Opportunity oldOpp = (Opportunity)old;
                if (newOpp.StageName != oldOpp.StageName) {
                    oppIds.add(newOpp.Id);
                }
            }
        }
        opportunityIdsToSync.addAll(oppIds);
    }
}
