public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    // Static set to track which opportunities we've already created tasks for in this transaction
    private static Set<Id> tasksCreated = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        List<Task> tasksToInsert = new List<Task>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity oppNew = triggerNew[i];
            Opportunity oppOld = triggerOld[i];

            // Check if Amount actually changed
            if (oppNew.Amount != oppOld.Amount) {
                // Use TAF's counter to detect if this is the first pass in afterUpdate context
                // This helps us avoid creating duplicate tasks when the rounding action re-updates records
                Integer timesSeen = TriggerBase.idToNumberOfTimesSeenAfterUpdate.get(oppNew.Id);

                // Only create a task if this is the first time we're seeing this opportunity
                // in the afterUpdate context, and we haven't already created a task for it
                if (timesSeen == 1 && !tasksCreated.contains(oppNew.Id)) {
                    Task t = new Task(
                        Subject = 'Amount changed',
                        WhatId = oppNew.Id,
                        Status = 'Completed'
                    );
                    tasksToInsert.add(t);
                    tasksCreated.add(oppNew.Id);
                }
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
